import assert from 'node:assert/strict'
import { copyFile, mkdtemp, writeFile } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { dirname, join } from 'node:path'
import { after, before, test } from 'node:test'
import { fileURLToPath } from 'node:url'
import type { Transcript } from '../shared/meetings.ts'

/**
 * Two genuinely different voices reading in turn, generated by `npm run fixtures`.
 * The point of the feature is telling them apart across meetings, so a fixture with
 * one voice would prove nothing.
 */
const FIXTURE = join(dirname(fileURLToPath(import.meta.url)), '..', '..', 'spike', 'fixtures', 'two-speakers.wav')

let dir: string
let transcript: Transcript
let available = true
let voices: typeof import('./voices.ts')

// The turns the fixture was built from: A speaks, then B, then A, then B.
const SEGMENTS = [
  { t0: 0.0, t1: 6.6, speaker: 'SPEAKER_00', text: 'a1' },
  { t0: 7.2, t1: 11.9, speaker: 'SPEAKER_01', text: 'b1' },
  { t0: 12.5, t1: 17.9, speaker: 'SPEAKER_00', text: 'a2' },
  { t0: 18.4, t1: 22.8, speaker: 'SPEAKER_01', text: 'b2' },
]

before(async () => {
  dir = await mkdtemp(join(tmpdir(), 'voices-test-'))
  process.env['VOICES_FILE'] = join(dir, 'voices.json')
  voices = await import('./voices.ts')

  transcript = {
    id: 'fixture',
    startedAt: '2026-08-27T14:00:00+07:00',
    durationSec: 23,
    speakers: { SPEAKER_00: 'Speaker 1', SPEAKER_01: 'Speaker 2' },
    segments: SEGMENTS,
  }
  await writeFile(join(dir, 'transcript.json'), JSON.stringify(transcript))
  await copyFile(FIXTURE, join(dir, 'loopback.wav')).catch(() => {
    available = false
  })
})

after(() => {
  delete process.env['VOICES_FILE']
})

const skip = () => !available

test('voices: a named voice is recognised again, and a different one is not', { skip: skip() }, async () => {
  assert.deepEqual(await voices.knownVoices(), [], 'starts with nothing learned')

  await voices.remember(dir, transcript, 'SPEAKER_00', 'พี่โจ้')
  assert.deepEqual(await voices.knownVoices(), ['พี่โจ้'])

  // The same voice in the same recording must come back with the name on it.
  assert.equal(await voices.identify(dir, transcript, 'SPEAKER_00'), 'พี่โจ้')

  // The other speaker must not. A wrong name attached to someone else's words is
  // worse than an unnamed speaker.
  assert.equal(await voices.identify(dir, transcript, 'SPEAKER_01'), null)
})

test('voices: forgetting a voice stops it matching', { skip: skip() }, async () => {
  await voices.remember(dir, transcript, 'SPEAKER_01', 'น้องมิ้น')
  assert.equal(await voices.identify(dir, transcript, 'SPEAKER_01'), 'น้องมิ้น')

  await voices.forget('น้องมิ้น')
  assert.equal(await voices.identify(dir, transcript, 'SPEAKER_01'), null)
  assert.ok(!(await voices.knownVoices()).includes('น้องมิ้น'))
})

test('voices: a speaker with almost no audio is not learned', { skip: skip() }, async () => {
  // An embedding from a fragment is mostly noise, and a bad one poisons every later
  // match, so too little audio must produce nothing rather than something wrong.
  const brief: Transcript = { ...transcript, segments: [{ t0: 0, t1: 0.4, speaker: 'SPEAKER_00', text: 'x' }] }
  await voices.remember(dir, brief, 'SPEAKER_00', 'ไม่ควรจำ')
  assert.ok(!(await voices.knownVoices()).includes('ไม่ควรจำ'))
})
